selected.compute:
options = read('/input/options')
ids = [x['id'] for x in options]
result = []
for k in range(goal['min_count'], goal['max_count'] + 1):
    for pick in combinations(ids, k):
        candidate = list(pick)
        if valid(candidate):
            result = candidate
            break
    if result:
        break

selected.effects:
if exists('/output/selection'):
    current = read('/output/selection')
    if not valid(current):
        status('report')
else:
    write('/output/selection', result)
if status('report') == 'not_sent':
    send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')
